function themePref(){
  var v=localStorage.getItem('t');
  return (v==='l'||v==='d'||v==='s')?v:'s';
}
function applyTheme(){
  var pref=themePref();
  var dark=pref==='d'||(pref==='s'&&!!(window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches));
  document.body.classList.toggle('dark',dark);
  document.body.classList.toggle('light',!dark);
  themeLabel();
  var ico=document.getElementById('themeIco'); if(ico)ico.textContent=pref==='l'?'☀️':(pref==='d'?'🌙':'🌗');
  var mc=document.querySelector('meta[name="theme-color"]'); if(mc)mc.setAttribute('content',dark?'#070a16':'#f4f5fb');
}
function themeLabel(){
  var t=T[curLang]||T.en, pref=themePref();
  var tx=document.getElementById('themeBtnTx');
  if(tx)tx.textContent=pref==='l'?t.thLight:(pref==='d'?t.thDark:t.thSystem);
  var menu=document.getElementById('themeMenu');
  if(menu){var items=menu.querySelectorAll('.mi');for(var i=0;i<items.length;i++)items[i].classList.toggle('sel',items[i].getAttribute('data-v')===pref);}
}
function closeMenus(){
  var cs=document.querySelectorAll('.ctl.open');
  for(var i=0;i<cs.length;i++){cs[i].classList.remove('open');var b=cs[i].querySelector('.ctl-btn');if(b)b.setAttribute('aria-expanded','false');}
}
function toggleMenu(which){
  var ctl=document.getElementById(which==='lang'?'langCtl':'themeCtl');
  if(!ctl)return;
  var was=ctl.classList.contains('open');
  closeMenus();
  if(!was){ctl.classList.add('open');var b=ctl.querySelector('.ctl-btn');if(b)b.setAttribute('aria-expanded','true');}
}
function pickLang(code){
  closeMenus();
  var it=document.querySelector('#langMenu .mi[data-v="'+code+'"]');
  if(it){document.getElementById('langBtnTx').textContent=it.textContent;
    var all=document.querySelectorAll('#langMenu .mi');
    for(var i=0;i<all.length;i++)all[i].classList.toggle('sel',all[i]===it);}
  setLang(code);
}
function pickTheme(v){ closeMenus(); setTheme(v); }
document.addEventListener('click',function(e){if(!e.target.closest('.ctl'))closeMenus();});
document.addEventListener('keydown',function(e){if(e.key==='Escape')closeMenus();});
function setTheme(v){
  localStorage.setItem('t',(v==='l'||v==='d'||v==='s')?v:'s');
  applyTheme();
}

