  var mb=(f.size/1024/1024).toFixed(1);
  var fn=document.getElementById('fn');
  fn.textContent='\u2713 '+(f.name.length>35?f.name.substring(0,32)+'...':f.name)+' \u00b7 '+mb+' MB';
  fn.style.display='inline-flex';
